 * runTransaction consumes the next outcome, "OK", "RETRY" or "FATAL". Once the
 * script runs out every further call succeeds.
 */
class FlakyDatabase {
    private final String[] script;
    private int used;

    FlakyDatabase(String... script) {
        this.script = script;
    }

    int attempts() {
        return used;
    }

    String runTransaction(String sql) {
        String outcome = used < script.length ? script[used] : "OK";
        used++;
        if ("RETRY".equals(outcome)) {
            throw new TransientDbException("deadlock on " + sql);
        }
        if ("FATAL".equals(outcome)) {
            throw new FatalDbException("bad SQL: " + sql);
        }
        return "OK:" + sql;
    }
}

