public class RetryingTransactionTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            FlakyDatabase healthy = new FlakyDatabase("OK");
            check("a first-try success is returned straight away", "OK:SELECT 1",
                    RetryingTransaction.runWithRetry(healthy, "SELECT 1", 5));
            check("a success costs exactly one attempt", 1, healthy.attempts());

            FlakyDatabase flaky = new FlakyDatabase("RETRY", "RETRY", "OK");
            check("two deadlocks then success", "OK:UPDATE t",
                    RetryingTransaction.runWithRetry(flaky, "UPDATE t", 5));
            check("it took three attempts", 3, flaky.attempts());

            FlakyDatabase hopeless = new FlakyDatabase("RETRY", "RETRY", "RETRY", "OK");
            check("running out of attempts gives up", "GAVE UP after 3 attempts",
                    RetryingTransaction.runWithRetry(hopeless, "UPDATE t", 3));
            check("it stopped at the attempt limit", 3, hopeless.attempts());

            FlakyDatabase broken = new FlakyDatabase("RETRY", "FATAL", "OK");
            check("a fatal error is not retried", "FATAL",
                    RetryingTransaction.runWithRetry(broken, "DELETE t", 5));
            check("a fatal error stops after the second attempt", 2, broken.attempts());

            FlakyDatabase untouched = new FlakyDatabase("OK");
            check("zero attempts never touches the database", "GAVE UP after 0 attempts",
                    RetryingTransaction.runWithRetry(untouched, "SELECT 1", 0));
            check("zero attempts really made no calls", 0, untouched.attempts());

            check("backoff for the first wait", 100, RetryingTransaction.backoffMillis(1));
            check("backoff doubles", 200, RetryingTransaction.backoffMillis(2));
            check("backoff keeps doubling", 400, RetryingTransaction.backoffMillis(3));
            check("backoff reaches the cap", 800, RetryingTransaction.backoffMillis(4));
            check("backoff stays at the cap", 800, RetryingTransaction.backoffMillis(9));
            check("backoff for attempt 0", 0, RetryingTransaction.backoffMillis(0));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- the retry policy should handle it, but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

