/**
 * TASK: Implement a retry policy around a flaky database.
 *
 * runWithRetry(db, sql, maxAttempts) calls db.runTransaction(sql) up to
 * maxAttempts times:
 *   - a successful call returns its result immediately,
 *   - a TransientDbException means try again (if any attempts are left),
 *   - a FatalDbException means stop at once and return "FATAL" -- retrying a
 *     broken statement would only waste the database's time,
 *   - if every attempt failed transiently, return "GAVE UP after N attempts"
 *     where N is maxAttempts.
 *   maxAttempts of 0 (or less) never calls the database at all and reports
 *   "GAVE UP after 0 attempts".
 *
 * backoffMillis(attempt) is how long a caller would wait before attempt
 * number "attempt" (1 is the first retry). It doubles each time starting at
 * 100 and is capped at 800: 1 -> 100, 2 -> 200, 3 -> 400, 4 -> 800, 5 -> 800,
 * 9 -> 800. Any attempt of 0 or less is 0. Do NOT actually sleep.
 */
public class RetryingTransaction {

    public static String runWithRetry(FlakyDatabase db, String sql, int maxAttempts) {
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return db.runTransaction(sql);
            } catch (FatalDbException e) {
                return "FATAL";
            } catch (TransientDbException e) {
                // try again while attempts remain
            }
        }
        return "GAVE UP after " + Math.max(maxAttempts, 0) + " attempts";
    }

    public static int backoffMillis(int attempt) {
        if (attempt <= 0) {
            return 0;
        }
        int wait = 100;
        for (int i = 1; i < attempt && wait < 800; i++) {
            wait *= 2;
        }
        return Math.min(wait, 800);
    }
}
